def key_report(rows, expected_rows):
    ids = [r["order_id"] for r in rows]
    return {
        "rows": len(ids),
        "distinct_keys": len(set(ids)),
        "duplicates": sorted({i for i in ids if ids.count(i) > 1}),
        "count_ok": len(ids) == expected_rows,
    }

rows = [{"order_id": 1}, {"order_id": 2}, {"order_id": 2}, {"order_id": 3}]
print(sorted(key_report(rows, 5).items()))

