SOURCE = {i: {"order_id": i, "amount_cents": 100 * i, "status": "paid" if i % 2 else "failed"} for i in range(1, 21)}
table = {k: dict(v) for k, v in SOURCE.items() if k != 9}
table[4]["amount_cents"] += 1
table[15]["status"] = "paid" if SOURCE[15]["status"] == "failed" else "failed"

import random

sample = sorted(random.Random(3).sample(sorted(SOURCE), 8))

def spot_check(table, source, ids):
    problems = {}
    for i in ids:
        if i not in table:
            problems[i] = ["missing"]
        else:
            diff = sorted(k for k in source[i] if source[i][k] != table[i].get(k))
            if diff:
                problems[i] = diff
    return dict(sorted(problems.items()))

print(sample)
print(spot_check(table, SOURCE, sample))
